import { render, screen } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import UserStats from './UserStats';

describe('UserStats', () => {
  it('displays active and inactive user counts correctly', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: true },
      { id: 2, name: 'User 2', isActive: false },
      { id: 3, name: 'User 3', isActive: true },
    ];

    render(<UserStats users={users} />);

    expect(screen.getByText(/Active Users: 2/i)).toBeInTheDocument();
    expect(screen.getByText(/Inactive Users: 1/i)).toBeInTheDocument();
  });

  it('displays the correct percentage of active users', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: true },
      { id: 2, name: 'User 2', isActive: false },
      { id: 3, name: 'User 3', isActive: true },
      { id: 4, name: 'User 4', isActive: false },
    ];
    // 2 active out of 4 total -> 50%

    render(<UserStats users={users} />);

    expect(screen.getByText(/Active Percentage: 50%/i)).toBeInTheDocument();
  });

  it('handles empty user list gracefully', () => {
    render(<UserStats users={[]} />);

    expect(screen.getByText(/Active Users: 0/i)).toBeInTheDocument();
    expect(screen.getByText(/Inactive Users: 0/i)).toBeInTheDocument();
    expect(screen.getByText(/Active Percentage: 0%/i)).toBeInTheDocument();
  });
});

